-- Applied explicitly to a private application schema, not public or auth.
CREATE TABLE IF NOT EXISTS schema_version(id integer PRIMARY KEY CHECK(id=1),version integer NOT NULL);
INSERT INTO schema_version VALUES(1,1) ON CONFLICT DO NOTHING;
DO $$ BEGIN IF (SELECT version FROM schema_version WHERE id=1) <> 1 THEN RAISE EXCEPTION 'Unsupported Fusewall schema version'; END IF; END $$;
CREATE TABLE IF NOT EXISTS settings(id integer PRIMARY KEY CHECK(id=1),budget_micro bigint NOT NULL CHECK(budget_micro>=0),paused integer NOT NULL DEFAULT 0,version integer NOT NULL DEFAULT 1);
INSERT INTO settings(id,budget_micro) VALUES(1,10000000) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS keys(id text PRIMARY KEY,token_hash text NOT NULL UNIQUE,name text NOT NULL,client text NOT NULL,active integer NOT NULL,policy text NOT NULL,created double precision NOT NULL);
CREATE TABLE IF NOT EXISTS buckets(scope text PRIMARY KEY,ceiling bigint NOT NULL CHECK(ceiling>=0),spent bigint NOT NULL DEFAULT 0 CHECK(spent>=0),held bigint NOT NULL DEFAULT 0 CHECK(held>=0),CHECK(spent+held<=ceiling));
CREATE TABLE IF NOT EXISTS sessions(id text PRIMARY KEY,external_id text NOT NULL,key_id text NOT NULL REFERENCES keys(id),started double precision NOT NULL,status text NOT NULL DEFAULT 'active',policy text NOT NULL,calls integer NOT NULL DEFAULT 0,last_fingerprint text,repetitions integer NOT NULL DEFAULT 0,UNIQUE(key_id,external_id));
CREATE TABLE IF NOT EXISTS requests(id text PRIMARY KEY,key_id text NOT NULL REFERENCES keys(id),session_id text NOT NULL REFERENCES sessions(id),model text NOT NULL,status text NOT NULL,reason text NOT NULL,reserved bigint NOT NULL,actual bigint NOT NULL DEFAULT 0,input_tokens integer NOT NULL,output_tokens integer NOT NULL DEFAULT 0,created double precision NOT NULL,finished double precision,elapsed_ms bigint,scopes text NOT NULL,fingerprint text NOT NULL,idempotency text,rate_version text NOT NULL,policy_version integer NOT NULL,scenario text NOT NULL,rates text NOT NULL,lease_expires double precision NOT NULL DEFAULT (extract(epoch FROM clock_timestamp())+120),UNIQUE(key_id,idempotency));
CREATE INDEX IF NOT EXISTS requests_created ON requests(created DESC);
CREATE INDEX IF NOT EXISTS requests_key_status ON requests(key_id,status,created);
CREATE INDEX IF NOT EXISTS requests_session ON requests(session_id,created);
CREATE TABLE IF NOT EXISTS ledger(id text PRIMARY KEY,request_id text NOT NULL UNIQUE REFERENCES requests(id),amount bigint NOT NULL CHECK(amount>=0),created double precision NOT NULL,provenance text NOT NULL CHECK(provenance='simulated'));
CREATE OR REPLACE FUNCTION reject_ledger_mutation() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN RAISE EXCEPTION 'ledger is append-only'; END $$;
DROP TRIGGER IF EXISTS ledger_immutable ON ledger;
CREATE TRIGGER ledger_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON ledger FOR EACH STATEMENT EXECUTE FUNCTION reject_ledger_mutation();
CREATE TABLE IF NOT EXISTS events(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,created double precision NOT NULL,kind text NOT NULL,message text NOT NULL,reference text);
CREATE TABLE IF NOT EXISTS owner_sessions(token_hash text PRIMARY KEY,expires double precision NOT NULL,epoch text NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts(created double precision NOT NULL);
CREATE TABLE IF NOT EXISTS lab_lease(id integer PRIMARY KEY CHECK(id=1),token text NOT NULL,expires double precision NOT NULL);
